(() => {
  const svg = [...document.querySelectorAll('.pdialog__body .pdoc__diagram')].find((s) => getComputedStyle(s).display !== 'none');
  const vb = svg.viewBox.baseVal; const bad = [];
  const boxes = [...svg.querySelectorAll('rect.dg-box, rect.dg-pill, path.dg-box')].map((el) => ({ el, b: el.getBBox() }));
  for (const t of svg.querySelectorAll('text:not(.dg-badge text)')) {
    const b = t.getBBox(); if (!b.width) continue;
    if (b.x < vb.x || b.y < vb.y || b.x + b.width > vb.x + vb.width || b.y + b.height > vb.y + vb.height) bad.push('fuera: ' + t.textContent);
    const cx = b.x + b.width / 2, cy = b.y + b.height / 2;
    const host = boxes.filter(({ b: r }) => cx > r.x && cx < r.x + r.width && cy > r.y && cy < r.y + r.height).sort((p, q) => p.b.width * p.b.height - q.b.width * q.b.height)[0];
    if (host) { const r = host.b; const m = Math.min(b.x - r.x, r.x + r.width - b.x - b.width); if (m < 5) bad.push(t.textContent + ' margen ' + m.toFixed(1)); }
  }
  const scale = svg.getBoundingClientRect().width / vb.width;
  return JSON.stringify({ variant: svg.classList.contains('pdoc__diagram--wide') ? 'wide' : 'tall', scale: +scale.toFixed(3), px13: +(13 * scale).toFixed(1), bad });
})()

